// Verify the review-page signature: action 'view', company.invoice.view.exp HMAC.
const crypto = require('crypto');
const q = $input.first().json.query || {};
const secret = $env.AUTH_TOKEN_SECRET || '';
const company = String(q.company || '');
const num = String(q.invoice || '');
const exp = String(q.exp || '');
const action = String(q.action || '');
const sig = String(q.sig || '');
let ok = false;
if (secret && company && num && exp && action === 'view' && sig) {
  const expected = crypto.createHmac('sha256', secret).update(`${company}.${num}.${action}.${exp}`).digest('base64url');
  const a = Buffer.from(sig); const b = Buffer.from(expected);
  if (a.length === b.length && crypto.timingSafeEqual(a, b) && Number(exp) * 1000 > Date.now()) ok = true;
}
return [{ json: { ok, company, invoice: num, exp } }];

const crypto = require('crypto');
const base = $env.PUBLIC_BASE_URL || 'https://n8n2.ordrnow.com';
const secret = $env.AUTH_TOKEN_SECRET || '';
const row = $input.first().json;
const mk = (action) => {
  const exp = Math.floor(Date.now() / 1000) + 90 * 86400;
  const sig = crypto.createHmac('sha256', secret)
    .update(`${row.company_id}.${row.invoice_number}.${action}.${exp}`).digest('base64url');
  return `${base}/webhook/${action === 'approve' ? 'approve' : 'reject'}-invoice?invoice=${encodeURIComponent(row.invoice_number)}&company=${encodeURIComponent(row.company_id)}&exp=${exp}&action=${action}&sig=${encodeURIComponent(sig)}`;
};
const approveUrl = mk('approve');
const rejectUrl = mk('reject');
const money = (v) => '$' + Number(v ?? 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const statusBadge = (row.status === 'DRAFT')
  ? '<span style="background:#fef3c7;color:#92400e;padding:.2rem .6rem;border-radius:999px;font-size:.75rem">DRAFT — not sent</span>'
  : '<span style="background:#dcfce7;color:#166534;padding:.2rem .6rem;border-radius:999px;font-size:.75rem">' + (row.status || '') + '</span>';
const invoiceHtml = (row.last_client_html && String(row.last_client_html).trim().length > 10)
  ? String(row.last_client_html)
  : '<div style="padding:1.5rem;background:#f9fafb;border:1px dashed #d1d5db;border-radius:8px;color:#6b7280;font-family:Helvetica,Arial,sans-serif">No rendered preview stored for this invoice yet — approve to send, or regenerate the preview first.</div>';
const page = `<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Invoice ${row.invoice_number} - review</title></head>
<body style="margin:0;background:#f1f5f9;font-family:Helvetica,Arial,sans-serif">
<div style="max-width:760px;margin:0 auto;padding:1.25rem">
  <div style="background:#0f172a;color:#fff;border-radius:12px;padding:1.1rem 1.25rem;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:.5rem">
    <div><strong style="font-size:1.1rem">Invoice ${row.invoice_number}</strong>
      <div style="font-size:.8rem;color:#cbd5e1">${row.our_name || ''} &middot; ${row.project_name || ''} &middot; ${row.customer_name || ''} &middot; ${money(row.amount_due)}</div></div>
    ${statusBadge}
  </div>
  <div style="background:#fff;border-radius:12px;margin-top:1rem;padding:1.25rem;display:flex;gap:.75rem;justify-content:flex-end;box-shadow:0 1px 3px rgba(0,0,0,.08)">
    <a href="${rejectUrl}" style="padding:.7rem 1.4rem;border-radius:8px;border:1px solid #dc2626;color:#dc2626;text-decoration:none;font-weight:600">Reject</a>
    <a href="${approveUrl}" style="background:#16a34a;color:#fff;padding:.7rem 1.4rem;border-radius:8px;text-decoration:none;font-weight:600">Approve &amp; send to ${row.customer_name || 'client'}</a>
  </div>
  <div style="background:#fff;border-radius:12px;margin-top:1rem;padding:.75rem;box-shadow:0 1px 3px rgba(0,0,0,.08)">${invoiceHtml}</div>
  <p style="font-size:.75rem;color:#94a3b8;text-align:center;margin-top:1rem">This review link expires in 90 days.</p>
</div></body></html>`;
return [{ json: { html: page } }];

const q = $input.first().json.query || {};
const html = `<!doctype html><html><head><meta charset="utf-8"><title>Invalid link</title></head>
<body style="font-family:Helvetica,Arial,sans-serif;background:#f1f5f9;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0">
<div style="background:#fff;border-radius:12px;padding:2rem;max-width:420px;text-align:center;box-shadow:0 1px 3px rgba(0,0,0,.08)">
  <div style="font-size:2rem">&#128274;</div>
  <h2 style="margin:.5rem 0">This link is invalid or has expired</h2>
  <p style="color:#6b7280;font-size:.9rem">Ask the assistant to push the invoice preview to your phone again.</p>
</div></body></html>`;
return [{ json: { html } }];
